const { scoped } = require('./db/scoped');

function slugify(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function list(tenantId) {
  return scoped(tenantId).select('projects');
}

function create(tenantId, name) {
  return scoped(tenantId).insert('projects', { name, slug: slugify(name) });
}

function remove(tenantId, id) {
  scoped(tenantId).remove('tasks', { project_id: id });
  return scoped(tenantId).remove('projects', { id });
}

module.exports = { list, create, remove, slugify };
