const test = require('node:test');
const assert = require('node:assert');
const { log } = require('../src/db/pool');
const projects = require('../src/projects');

test('every project query is tenant scoped', () => {
  projects.list('t1');
  projects.remove('t1', 'p1');
  assert.ok(log.length >= 3);
  for (const q of log) {
    assert.match(q.sql, /tenant_id = \$1/);
    assert.strictEqual(q.params[0], 't1');
  }
});

test('slugs are url safe', () => {
  assert.strictEqual(projects.slugify('Q4 Launch Plan!'), 'q4-launch-plan');
});
